INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9de6974c-843b-4d6b-9b19-874c554ad61e', 'Verify Z-order of Test App 1 after switch (Per Iteration)', 'Retrieve the updated Z-order of Test App 1 to verify the new value was applied correctly.
