INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8e4310d5-fac0-463e-ad7c-da094d082fe2', 'Set Z-order of Test App 2 to swapped value (Per Iteration)', 'Set the Z-order of Test App 2 to the Z-order value previously held by Test App 1 to complete the Z-order swap.
