INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0258d61e-d1d2-4673-bca0-54a7889380dc', 'Verify Z-order of both apps are distinct after full switch (Per Iteration)', 'Retrieve the Z-order of both Test App 1 and Test App 2 and verify that their Z-order values are different from each other after the full swap.
