INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c46f4f33-0353-428d-8165-b3a212779016', 'Conditionally reboot device before test', 'Conditionally reboot the device based on the PRE_REQ_REBOOT_PVS configuration key. If set to Yes, the device is rebooted by invoking the Thunder Controller harakiri method and the script waits 150 seconds for the device to come back online.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.harakiri"}', 'The device should come back online successfully if reboot was configured.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.106120', '2026-08-05 10:05:21.106121');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b8ae75ae-68fe-40e7-8582-5e6862163fc8', 'Verify and activate required plugins', 'Retrieve the current activation state of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, and org.rdk.RDKWindowManager. Activate any plugin that is not already in the activated state.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.DownloadManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppPackageManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.RDKWindowManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All four required plugins should be in the activated state before test execution proceeds.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.107230', '2026-08-05 10:05:21.107231');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fe01d6f6-7234-481a-84d6-667d1a1a90ae', 'Subscribe to onAppDownloadStatus event', 'Register a WebSocket event listener to subscribe to the onAppDownloadStatus event from org.rdk.DownloadManager. Wait 5 seconds after registration.
{"jsonrpc": "2.0", "id": 2, "method": "org.rdk.DownloadManager.1.register", "params": {"event": "onAppDownloadStatus", "id": "client.events.1"}}', 'The onAppDownloadStatus event subscription should be established successfully and the WebSocket event listener should be active.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.108373', '2026-08-05 10:05:21.108374');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('aa0fb3b2-5f48-4de8-9724-92fe5e5710e4', 'Clear event buffer (Per Iteration)', 'For each of the AppManager_test_count (100) iterations, clear the event listener buffer to discard any stale events before the download operations for that iteration.', 'The event buffer should be cleared successfully at the start of each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.109570', '2026-08-05 10:05:21.109571');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('78344949-554f-4984-97ef-0c64168148be', 'Attempt download from invalid URL (Per Iteration)', 'Attempt to initiate a download using the DownloadManager download API with the configured invalid URL (http://invalid.com/<google_bundle>). This request is expected to fail.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "http://invalid.com/<google_bundle>"}}', 'The download API should return a failure response, indicating the DownloadManager correctly rejected the invalid URL for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.110634', '2026-08-05 10:05:21.110635');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d485af53-55e9-48c8-afc6-df509b2a3ffe', 'Verify DOWNLOAD_FAILURE event is received for invalid URL (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds to verify that an onAppDownloadStatus event carrying the DOWNLOAD_FAILURE status is received, confirming the DownloadManager correctly reported the failure for the invalid URL download attempt.
{"jsonrpc": "2.0", "method": "client.events.1.onAppDownloadStatus", "params": {"downloadStatus": "[{"downloadStatus": "DOWNLOAD_FAILURE"}]"}}', 'The onAppDownloadStatus event with DOWNLOAD_FAILURE status should be received within the monitoring period for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.112604', '2026-08-05 10:05:21.112700');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2a0ebd73-02b7-4206-af95-89c60b8b9d9f', 'Clear event buffer after invalid URL failure (Per Iteration)', 'Clear the event listener buffer after receiving the DOWNLOAD_FAILURE event to prepare for the valid URL download attempt.', 'The event buffer should be cleared successfully before initiating the valid URL download.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.114477', '2026-08-05 10:05:21.114478');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0567ad92-75cc-490d-9466-0f2ca31c105a', 'Download application bundle from valid URL (Per Iteration)', 'Initiate the download of the application bundle from the valid configured download URL using the DownloadManager download API.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<valid_app_download_url>/<google_bundle>"}}', 'The download API should return SUCCESS and provide a valid download ID for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.114893', '2026-08-05 10:05:21.114895');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bd155057-6b3d-4f7a-ad0e-d059865b2353', 'Verify successful onAppDownloadStatus event for valid URL (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds to receive the onAppDownloadStatus event for the valid URL download. Verify the event does not carry DOWNLOAD_FAILURE status, and parse the event to extract the downloadId and fileLocator fields. Confirm the event download ID matches the download ID returned by the download API, and the download ID is present in the fileLocator URL.
{"jsonrpc": "2.0", "method": "client.events.1.onAppDownloadStatus", "params": {"downloadStatus": "[{"downloadId": "<id>", "fileLocator": "<url>"}]"}}', 'The onAppDownloadStatus event should not contain DOWNLOAD_FAILURE, the download ID should match the API response, and the download ID should be present in the fileLocator URL for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.115946', '2026-08-05 10:05:21.115947');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0efbbc26-9446-4cc9-8e12-487f0a5963da', 'Delete downloaded package from device (Per Iteration)', 'Delete the successfully downloaded application bundle from the device storage using the DownloadManager delete API, providing the fileLocator URL obtained from the valid download event.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.delete", "params": {"fileLocator": "<filelocator_url>"}}', 'The delete API should return SUCCESS for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.117756', '2026-08-05 10:05:21.117757');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3161c7ae-a818-46ed-b89e-e317b09538b5', 'Verify downloaded package file is deleted from device storage (Per Iteration)', 'Verify that the downloaded package file no longer exists on the DUT by executing an SSH file listing command against the fileLocator URL path.
ls -l <filelocator_url>', 'The file listing command should return a "No such file or directory" response, confirming that the package was successfully deleted from device storage for each iteration.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.119537', '2026-08-05 10:05:21.119539');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7cf8caa9-f0f8-4e49-89a0-e8677b5a6332', 'Repeat invalid and valid URL download validation for all iterations', 'Repeat Steps 4 through 11 for all AppManager_test_count (100) configured iterations.', 'Every iteration should successfully reject the invalid URL download with a DOWNLOAD_FAILURE event, complete the valid URL download, receive the correct onAppDownloadStatus event, delete the package, and confirm file removal from device storage.', '7103a207-031b-4ef4-ba17-9a8f0e3498a1', '2026-08-05 10:05:21.121194', '2026-08-05 10:05:21.121196');
