INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e1a51839-b278-4bfb-b252-99d1026ec90c', 'STEP 3', 'Configure ACS to send GET task request for getting multiple parameters including Device.X_CISCO_COM_DeviceControl.LanManagementEntry.1.LanMode, Device.DeviceInfo.Manufacturer.', 'Should successfully return 200 as status code and a non-empty query response.', '00f1efec-6512-426b-85c8-d1d29bfd4df4', '2026-08-05 06:00:32.336502', '2026-08-05 06:00:32.336504');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b0717530-8895-44f9-aeb3-976bd04542f7', 'STEP 4', 'Configure ACS to send a search query for getting multiple parameter values.', 'Should successfully return 200 as status code and parse the query response to retrieve multiple parameter values.', '00f1efec-6512-426b-85c8-d1d29bfd4df4', '2026-08-05 06:00:32.337339', '2026-08-05 06:00:32.337340');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('74a0ecce-1dd1-4619-a79e-a12f4f6127a8', 'STEP 5', 'Get the multiple parameter values from DUT.', 'Should get multiple parameter values from the DUT successfully.', '00f1efec-6512-426b-85c8-d1d29bfd4df4', '2026-08-05 06:00:32.338144', '2026-08-05 06:00:32.338145');
