INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0817b304-7d28-48b2-b859-12cc878a73b5', 'STEP 7', 'Revert the parameters modified during prerequisite to initial values', 'Reverted successfully', '00f1efec-6512-426b-85c8-d1d29bfd4df4', '2026-08-05 06:00:32.339829', '2026-08-05 06:00:32.339830');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bee2cca7-29b1-49cf-846d-8d6395a6feb9', 'STEP 8', 'Unload tdkbtr181 and sysutil module.', 'tdkbtr181 and sysutil module should be loaded successfully.', '00f1efec-6512-426b-85c8-d1d29bfd4df4', '2026-08-05 06:00:32.340078', '2026-08-05 06:00:32.340078');
DELETE FROM test_step WHERE script_id = '1a347913-aa8c-4006-b89b-2a7c1427f967';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('08abf5b1-db10-4503-827b-32e3a6790059', 'STEP 1', '1.Load the module
2.Get the current lan mode and set the mode to bridge-static
3.Get the current status of Device.WiFi.X_RDK-CENTRAL_COM_ForceDisable,Device.WiFi.Radio.1.Enable and Device.WiFi.Radio.2.Enable
4.Enable Device.WiFi.X_RDK-CENTRAL_COM_ForceDisable
5.Device.WiFi.Radio.1.Enable and Device.WiFi.Radio.2.Enable  should be disabled
6.Revert the  Device.WiFi.X_RDK-CENTRAL_COM_ForceDisable to previous
7.Verify that Device.WiFi.Radio.1.Enable and Device.WiFi.Radio.2.Enable also go to previous after revert operation
8.Revert the LAN mode to previous state
7.Unload the module', 'On Enabling Device.WiFi.X_RDK-CENTRAL_COM_ForceDisable 2.4G and 5G radio should be disabled in bridge-mode', '1a347913-aa8c-4006-b89b-2a7c1427f967', '2026-07-31 10:04:26.466018', '2026-07-31 10:04:26.466019');
DELETE FROM test_step WHERE script_id = '36525c09-f769-414b-a9ee-9c9ea08d3d15';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('08dbefc6-a7f4-4b93-b62e-276ef39476f3', 'Conditionally reboot device before test', 'Conditionally reboot the device based on the PRE_REQ_REBOOT configuration key. If set to Yes, the device is rebooted by invoking the Thunder Controller harakiri method and the script waits 150 seconds for the device to come back online.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.harakiri"}', 'The device should come back online successfully if reboot was configured.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.580595', '2026-08-06 05:01:38.580596');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('baa25483-ee5c-4351-a1d5-a54464dd642f', 'Validate device resource usage state', 'Check the activation state of the DeviceInfo plugin and activate it if needed, then validate that the device CPU and memory usage are within the acceptable range before proceeding.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@DeviceInfo"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "DeviceInfo"}}', 'Device CPU and memory usage should be within the expected range, confirming the device is in a healthy state before testing.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.581512', '2026-08-06 05:01:38.581513');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('abafb711-aee8-43a9-b301-2367de3dd4c6', 'Verify and activate required plugins', 'Retrieve the current activation state of org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager. Activate any plugin that is not already in the activated state.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.DownloadManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppPackageManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All three required plugins should be in the activated state before test execution proceeds.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.582343', '2026-08-06 05:01:38.582345');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2946e514-9708-4bbe-9267-95e5ca8c5b37', 'Subscribe to onAppInstallationStatus event', 'Register a WebSocket event listener to subscribe to the onAppInstallationStatus event from org.rdk.AppPackageManager. Wait 3 seconds after registration.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.1.register", "params": {"event": "onAppInstallationStatus", "id": "client.events.1"}}', 'The onAppInstallationStatus event subscription should be established successfully and the WebSocket event listener should be active.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.583189', '2026-08-06 05:01:38.583190');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('51cf29df-d4ba-4a61-bff8-0b80f8504787', 'Clear event buffer (Per Iteration)', 'For each of the AppManager_test_count (100) iterations, clear the event listener buffer to discard any stale events before the install operations for that iteration.', 'The event buffer should be cleared successfully at the start of each iteration.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.583410', '2026-08-06 05:01:38.583410');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c7e34c00-0c05-48a3-a350-d19e3fbc9e4c', 'Check if application is pre-installed and uninstall if present (Per Iteration)', 'Query the installed package list to check whether com.rdkcentral.google is already installed. If present, uninstall it and wait for the onAppInstallationStatus event with status UNINSTALLED before proceeding with the download.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.1.listPackages"}

{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.uninstall", "params": {"packageId": "com.rdkcentral.google"}}', 'If pre-installed, the application should be uninstalled successfully and the onAppInstallationStatus event with UNINSTALLED status should be received before proceeding.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.583598', '2026-08-06 05:01:38.583599');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f1c70915-d426-488c-82ca-161d15444c52', 'Download application bundle (Per Iteration)', 'Initiate the download of the application bundle from the configured download URL using the DownloadManager download API.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}', 'The application bundle download should complete successfully and return a valid download ID.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.584469', '2026-08-06 05:01:38.584470');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('66b11761-af6a-4055-9e81-f4ca28eaa337', 'Install application on the device (Per Iteration)', 'Retrieve the PACKAGEMANAGER_FILE_LOCATOR device configuration key to construct the installation file path, then install the downloaded application bundle using the AppPackageManager install API.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.install", "params": {"packageId": "com.rdkcentral.google", "fileLocator": "<PACKAGEMANAGER_FILE_LOCATOR>/<download_id>"}}', 'The install API should return SUCCESS and initiate the installation of the application for each iteration.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.585283', '2026-08-06 05:01:38.585284');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a0fcd8f8-7de6-47d1-8ee1-23bfb107d588', 'Verify onAppInstallationStatus INSTALLED event received (Per Iteration)', 'Monitor the event buffer for up to 120 seconds to verify that an onAppInstallationStatus event with INSTALLED status is received for com.rdkcentral.google.
{"jsonrpc": "2.0", "method": "client.events.1.onAppInstallationStatus", "params": {"appId": "com.rdkcentral.google", "status": "INSTALLED"}}', 'The onAppInstallationStatus event with INSTALLED status should be received for com.rdkcentral.google within the monitoring period.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.586135', '2026-08-06 05:01:38.586136');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('297c2bd1-7419-44a5-8c70-5a26c3b4af01', 'Retrieve installed package list and extract metadata (Per Iteration)', 'Query the AppPackageManager package list to retrieve the entry for com.rdkcentral.google and extract the package metadata fields: version, digest, and sizeKb.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.1.listPackages"}', 'The package list should be retrieved successfully and the com.rdkcentral.google entry should contain non-empty version, digest, and sizeKb fields.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.586346', '2026-08-06 05:01:38.586347');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9bb95034-c783-4b9e-8d67-fae92a465146', 'Capture or verify metadata consistency (Per Iteration)', 'On the first iteration, capture the retrieved metadata (version, digest, sizeKb) as the baseline expected metadata. On all subsequent iterations, compare the retrieved metadata fields against the captured baseline values to verify consistency.', 'For the first iteration, the baseline metadata should be captured successfully. For all subsequent iterations, the retrieved version, digest, and sizeKb values should exactly match the baseline, confirming metadata consistency across installs.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.586571', '2026-08-06 05:01:38.586571');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7c68530c-a259-4fc7-9f57-1d0552641862', 'Uninstall application from the device (Per Iteration)', 'Uninstall com.rdkcentral.google from the device using the AppPackageManager uninstall API.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.uninstall", "params": {"packageId": "com.rdkcentral.google"}}', 'The uninstall API should return SUCCESS and the application should be removed for each iteration.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.587400', '2026-08-06 05:01:38.587401');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('61c335bf-3481-49bf-a725-1744984ecd75', 'Verify application is removed from package list (Per Iteration)', 'Query the installed package list to confirm that com.rdkcentral.google no longer appears as an installed package after uninstallation.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.AppPackageManager.1.listPackages"}', 'The com.rdkcentral.google package should not be present in the installed packages list after uninstallation.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.588827', '2026-08-06 05:01:38.588828');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c09048cc-dad9-4dc2-919c-37296e4329c7', 'Repeat metadata verification for all iterations', 'Repeat Steps 5 through 13 for all AppManager_test_count (100) configured iterations.', 'Every iteration should successfully install the application, receive the onAppInstallationStatus event, retrieve metadata with consistent version, digest, and sizeKb values matching the baseline, and confirm successful removal from the package list after uninstallation.', '36525c09-f769-414b-a9ee-9c9ea08d3d15', '2026-08-06 05:01:38.589048', '2026-08-06 05:01:38.589049');
