INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('91ae0d60-74c7-4ee1-bfb6-c72314356983', 'Repeat focus switch validation for all iterations', 'Repeat Steps 7 through 11 for all AppManager_test_count (100) configured iterations.', 'Every iteration should successfully switch focus between both applications and receive the corresponding onFocus events with the correct application instance identifiers, confirming reliable focus management across all iterations.', '63a847e3-9477-416c-9021-499edb837574', '2026-08-05 10:05:20.671711', '2026-08-05 10:05:20.671712');
