INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6e4ea7eb-ed9e-4206-9752-240a41f5d6c0', 'Conditionally reboot device before test', 'Conditionally reboot the device based on the PRE_REQ_REBOOT_PVS configuration key. If set to Yes, the device is rebooted by invoking the Thunder Controller harakiri method and the script waits 150 seconds for the device to come back online.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.harakiri"}', 'The device should come back online successfully if reboot was configured.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.123292', '2026-08-06 04:25:44.123294');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3c345156-4882-4296-b964-a2a77ecbcbf5', 'Verify and activate required plugins', 'Retrieve the current activation state of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, and org.rdk.RDKWindowManager. Activate any plugin that is not already in the activated state.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.DownloadManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppPackageManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.RDKWindowManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All four required plugins should be in the activated state before test execution proceeds.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.124214', '2026-08-06 04:25:44.124216');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0f53afb8-61cb-4213-b964-c7f0985c1bb7', 'Subscribe to onAppDownloadStatus event', 'Register a WebSocket event listener to subscribe to the onAppDownloadStatus event from org.rdk.DownloadManager. Wait 5 seconds after registration to ensure the listener is ready.
{"jsonrpc": "2.0", "id": 2, "method": "org.rdk.DownloadManager.1.register", "params": {"event": "onAppDownloadStatus", "id": "client.events.1"}}', 'The onAppDownloadStatus event subscription should be established successfully and the WebSocket event listener should be active.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.124459', '2026-08-06 04:25:44.124460');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1b414f3b-0bdf-474f-9636-2943853bd016', 'Download application bundle (Per Iteration)', 'For each of the AppManager_test_count (100) iterations, initiate the download of the application bundle from the configured download URL using the DownloadManager download API.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}', 'The download API should return SUCCESS and provide a unique download ID for each iteration.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.124663', '2026-08-06 04:25:44.124664');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4d4bcc62-6e81-408b-b4d5-dfacc056d124', 'Monitor event buffer for onAppDownloadStatus (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds after initiating the download to receive the onAppDownloadStatus event confirming the download completion.', 'The onAppDownloadStatus event should be received within the monitoring period for each iteration.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.124868', '2026-08-06 04:25:44.124869');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cd4738ee-966e-40f5-bc75-a9774b387c40', 'Verify unique download ID and parse file locator (Per Iteration)', 'Parse the received onAppDownloadStatus event to extract the downloadId and fileLocator fields from the event payload. Verify that the download ID is unique and has not appeared in any previous iteration, and that the download ID is embedded in the fileLocator URL.
{"jsonrpc": "2.0", "method": "client.events.1.onAppDownloadStatus", "params": {"downloadStatus": "[{"downloadId": "<id>", "fileLocator": "<url>"}]"}}', 'The download ID should be unique across all previous iterations, and the fileLocator URL should contain the download ID, confirming correct download identification.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.126402', '2026-08-06 04:25:44.126403');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b98ae88c-3db6-40b6-8b29-35a1119239f4', 'Delete downloaded package from device (Per Iteration)', 'Delete the downloaded application bundle from the device storage using the DownloadManager delete API, providing the fileLocator URL obtained from the onAppDownloadStatus event.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.delete", "params": {"fileLocator": "<filelocator_url>"}}', 'The delete API should return SUCCESS for each iteration.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.127237', '2026-08-06 04:25:44.127238');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('364c9b8a-d720-4776-9b83-bfee93ec5661', 'Verify package file is deleted from device storage (Per Iteration)', 'Verify that the downloaded package file no longer exists on the DUT by executing an SSH file listing command against the file path extracted from the fileLocator URL.
ls -l <file_path>', 'The file listing command should return a "No such file or directory" response, confirming that the package was successfully deleted from device storage for each iteration.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.127466', '2026-08-06 04:25:44.127467');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9fb36535-4e15-446f-97ee-940553731617', 'Repeat download and delete validation for all iterations', 'Repeat Steps 4 through 8 for all AppManager_test_count (100) configured iterations.', 'Every iteration should successfully download the application bundle, receive the onAppDownloadStatus event with a unique download ID, delete the package, and confirm the file is no longer present on the device.', '79e212ca-3bc3-44d1-aee5-b234d6eac381', '2026-08-06 04:25:44.128286', '2026-08-06 04:25:44.128287');
