INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1158b3bd-facd-4434-a555-bad13ed6f34f', 'STEP 1', '1. Load wifiagent module
2. Using WIFIAgent_Get, get and save Device.WiFi.Radio.2.Enable
3. Using WIFIAgent_Get, get and save Device.WiFi.Radio.2.LastChange
4. Using WIFIAgent_Set, toggle value of Device.WiFi.Radio.2.Enable
5. Using WIFIAgent_Get, get  the value of Device.WiFi.Radio.2.LastChange and compare it with previous value
6. Check if lastchange value is less than the previously saved value
7. Restrore values of Device.WiFi.Radio.2.Enable, Device.WiFi.Radio.2.LastChange
8. Unload wifiagent module', 'LastChange value should change on enabling/disabling Radio.2', '52c789d8-b68a-4bc0-980d-971a4c538fd8', '2026-07-31 10:56:28.574612', '2026-07-31 10:56:28.574613');
