INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e3e1bdd1-5bb8-409c-b58e-38557f602341', 'Conditionally reboot device before test', 'Conditionally reboot the device based on the PRE_REQ_REBOOT_PVS configuration key. If set to Yes, the device is rebooted by invoking the Thunder Controller harakiri method and the script waits 150 seconds for the device to come back online.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.harakiri"}', 'The device should come back online successfully if reboot was configured.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.957887', '2026-08-06 04:24:00.957889');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24381fd6-3507-4d42-a79f-213db62ed5bb', 'Verify and activate required plugins', 'Retrieve the current activation state of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, and org.rdk.RDKWindowManager. Activate any plugin that is not already in the activated state.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.DownloadManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppPackageManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.RDKWindowManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All four required plugins should be in the activated state before test execution proceeds.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.959221', '2026-08-06 04:24:00.959222');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cae8add1-ce51-4dc9-9f42-442e02ce9190', 'Record initial disk usage of download directory', 'Record the initial disk usage of the download staging directory via SSH to establish a baseline for post-deletion disk usage comparison.
du -sk <file_locator> | awk ''{print $1}''', 'The initial disk usage value should be retrieved successfully and stored as the baseline for disk usage validation.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.960158', '2026-08-06 04:24:00.960159');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('33320cd4-e235-4968-b486-605a052f7a2f', 'Subscribe to onAppDownloadStatus event', 'Register a WebSocket event listener to subscribe to the onAppDownloadStatus event from org.rdk.DownloadManager. Wait 5 seconds after registration.
{"jsonrpc": "2.0", "id": 2, "method": "org.rdk.DownloadManager.1.register", "params": {"event": "onAppDownloadStatus", "id": "client.events.1"}}', 'The onAppDownloadStatus event subscription should be established successfully and the WebSocket event listener should be active.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.960989', '2026-08-06 04:24:00.960990');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('149af8c1-90fe-4583-9ebe-80cee517ab13', 'Clear event buffer and initiate large file download (Per Iteration)', 'For each of the AppManager_test_count (100) iterations, clear the event buffer and initiate the download of the large validation file ("1_GB_File.bin") from the configured URL using the DownloadManager download API. Wait 15 seconds after initiating the download.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<Large_Validation_File>"}}', 'The download API should return SUCCESS and provide a download ID for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.961715', '2026-08-06 04:24:00.961715');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('276170e0-c6ff-43f3-9362-d45995593be3', 'Check download progress is in progress (Per Iteration)', 'Wait 2 seconds after the download initiation, then query the download progress using the DownloadManager progress API to verify the download has started but is not yet complete (progress > 0 and < 100).
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.progress", "params": {"downloadId": "<download_id>"}}', 'The download progress should be greater than 0 and less than 100, confirming the download is actively in progress for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.962492', '2026-08-06 04:24:00.962493');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c2f65869-9ffb-4ef1-a947-702c57e3943e', 'Cancel the in-progress download (Per Iteration)', 'Cancel the active download using the DownloadManager cancel API with the download ID obtained from the download initiation response.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.cancel", "params": {"downloadId": "<download_id>"}}', 'The cancel API should return SUCCESS for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.963353', '2026-08-06 04:24:00.963353');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('af2ee8e3-f0e4-4ff9-bea1-eb0a35986581', 'Monitor event buffer for DOWNLOAD_FAILURE cancellation event (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds after the cancellation request to receive the onAppDownloadStatus event carrying the DOWNLOAD_FAILURE status, which confirms the download was cancelled.', 'The onAppDownloadStatus event with DOWNLOAD_FAILURE status should be received within the monitoring period for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.964890', '2026-08-06 04:24:00.964891');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd24e113-0c3f-4cf0-9338-38da4a58541d', 'Verify cancellation event download ID and file locator (Per Iteration)', 'Parse the received onAppDownloadStatus cancellation event to extract and verify the downloadId and fileLocator fields. The event download ID must match the download ID from the download initiation response, and the download ID must be present within the fileLocator URL string.
{"jsonrpc": "2.0", "method": "client.events.1.onAppDownloadStatus", "params": {"downloadStatus": "[{"downloadId": "<id>", "fileLocator": "<url>"}]"}}', 'The cancellation event download ID should match the initiated download ID, and the download ID should be present in the fileLocator URL, confirming the event relates to the correct download.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.966656', '2026-08-06 04:24:00.966657');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c4fc6ed8-59ac-4477-9fd7-b66081f3f50b', 'Delete the partially downloaded package from device (Per Iteration)', 'Delete the partially downloaded file from the device storage using the DownloadManager delete API, providing the fileLocator URL obtained from the cancellation event.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.delete", "params": {"fileLocator": "<filelocator_url>"}}', 'The delete API should return SUCCESS for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.966869', '2026-08-06 04:24:00.966869');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9b41049c-a88e-4926-ab62-c6e8f9f67069', 'Verify partial download file is deleted from device storage (Per Iteration)', 'Verify that the partially downloaded file no longer exists on the DUT by executing an SSH file listing command against the fileLocator URL path.
ls -l <filelocator_url>', 'The file listing command should return a "No such file or directory" response, confirming that the partially downloaded package was successfully removed from device storage for each iteration.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.967668', '2026-08-06 04:24:00.967669');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8638fbc2-7d64-497a-a403-4101c9b38608', 'Verify disk usage is restored to baseline after deletion (Per Iteration)', 'Check the current disk usage of the download staging directory via SSH and verify that it has not exceeded the initial baseline disk usage recorded before testing, confirming that no residual storage consumption remains after the cancel and delete operations.
du -sk <file_locator> | awk ''{print $1}''', 'The current disk usage should be less than or equal to the initial baseline disk usage value, confirming that disk space is correctly reclaimed after each cancel and delete cycle.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.968501', '2026-08-06 04:24:00.968502');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb585e2a-25cc-4aa9-9b4e-62ecdeb488c8', 'Repeat download cancel and delete validation for all iterations', 'Repeat Steps 5 through 12 for all AppManager_test_count (100) configured iterations.', 'Every iteration should successfully download the large file to an in-progress state, cancel the download, receive the DOWNLOAD_FAILURE cancellation event with correct identification, delete the partial package, and confirm disk usage is restored to the initial baseline.', '412ba6b3-484c-4f58-bda0-1a24cb58d407', '2026-08-06 04:24:00.969300', '2026-08-06 04:24:00.969301');
