INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bc9f3caf-a9f6-4d65-a723-347632d9e440', 'TEST STEP 6', 'Set Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.RDKRemoteDebugger.IssueType to "Device.wifi".', 'The DM value has been set successfully.', '7023ff8e-752a-42fb-b4e7-a4619d669786', '2026-07-28 10:16:20.833023', '2026-07-28 10:16:20.833024');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ce2328df-6152-4ccc-a318-d72aa978b8a9', 'TEST STEP 7', 'Check whether dynamic JSON file is created in below path /tmp/RDK-RRD-Device/etc/rrd/remote_debugger.json.', 'The JSON file should be created in the designated location', '7023ff8e-752a-42fb-b4e7-a4619d669786', '2026-07-28 10:16:20.833975', '2026-07-28 10:16:20.833976');
