INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('331d03f9-5ad4-4557-bbc1-544850b57702', 'TEST STEP 10', 'Revert the value of Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.RDKRemoteDebugger.IssueType, Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.RDKRemoteDebugger.Enable and Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.CDLDM.CDLModuleUrl to initial values.', 'The values must be reverted successfully.', '7023ff8e-752a-42fb-b4e7-a4619d669786', '2026-07-28 10:16:20.836764', '2026-07-28 10:16:20.836765');
