INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a6fbe2ac-a849-4ec4-a58b-89728c3c3847', 'Conditionally reboot device before test', 'Conditionally reboot the device based on the PRE_REQ_REBOOT_PVS configuration key. If set to Yes, the device is rebooted by invoking the Thunder Controller harakiri method and the script waits 150 seconds for the device to come back online.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.harakiri"}', 'The device should come back online successfully if reboot was configured.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.800511', '2026-08-05 10:05:20.800512');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('29d8e6f3-2f3a-4234-9a16-c9c431eb42fa', 'Verify and activate required plugins', 'Retrieve the current activation state of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, and org.rdk.RDKWindowManager. Activate any plugin that is not already in the activated state.
{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.DownloadManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppPackageManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.AppManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.status@org.rdk.RDKWindowManager"}

{"jsonrpc": "2.0", "id": 1, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All four required plugins should be in the activated state before test execution proceeds.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.801998', '2026-08-05 10:05:20.801999');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b3e36eba-3430-4526-9b89-06fd43a4187d', 'Record initial disk usage of download staging directory', 'Retrieve the initial disk usage of the download staging directory derived from PACKAGEMANAGER_FILE_LOCATOR via SSH to establish a baseline for post-deletion disk usage comparison.
du -sk <file_locator> | awk ''{print $1}''', 'The initial disk usage value (in KB) should be retrieved successfully and stored as the baseline for all disk usage validations.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.803795', '2026-08-05 10:05:20.803796');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ba9ef53f-9dc1-4c6c-9584-2ed3154646f3', 'Subscribe to onAppDownloadStatus event', 'Register a WebSocket event listener to subscribe to the onAppDownloadStatus event from org.rdk.DownloadManager. Wait 5 seconds after registration.
{"jsonrpc": "2.0", "id": 2, "method": "org.rdk.DownloadManager.1.register", "params": {"event": "onAppDownloadStatus", "id": "client.events.1"}}', 'The onAppDownloadStatus event subscription should be established successfully and the WebSocket event listener should be active.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.804100', '2026-08-05 10:05:20.804101');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fa5ab92f-b607-4124-9198-c42fb5e4d0e9', 'Initiate first download of validation file (Per Iteration)', 'For each of the AppManager_test_count (100) iterations, initiate the download of the 10 MB validation file ("10_MB_File.bin") from the configured URL using the DownloadManager download API. Wait 15 seconds after initiating the download.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/10_MB_File.bin"}}', 'The download API should return SUCCESS and provide a unique download ID for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.805604', '2026-08-05 10:05:20.805606');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('88dce18a-0ea5-4125-9443-fa9531cdd0a8', 'Verify onAppDownloadStatus event for first download (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds to receive the onAppDownloadStatus event for the first download. Parse the event to extract the downloadId and fileLocator fields.
{"jsonrpc": "2.0", "method": "client.events.1.onAppDownloadStatus", "params": {"downloadStatus": "[{"downloadId": "<id>", "fileLocator": "<url>"}]"}}', 'The onAppDownloadStatus event should be received within the monitoring period, providing the download ID and fileLocator for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.805938', '2026-08-05 10:05:20.805939');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6d4be649-0d37-4982-8f14-9c1eea76f9d8', 'Verify first download ID is unique (Per Iteration)', 'Confirm that the download ID received in the onAppDownloadStatus event has not appeared in any previous iteration of the test.', 'The first download ID should be unique and not present in the list of previously seen download IDs for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.806919', '2026-08-05 10:05:20.806921');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('840624dd-c3ee-4a30-a867-56fb6a32bb55', 'Verify downloaded file size via SSH (Per Iteration)', 'Measure the size of the downloaded file on the DUT via SSH and compare it against the expected package size of 10240 KB (Redownload_Package_Size_MB Ã— 1024).
du -sk <filelocator_url> | awk ''{print $1}''', 'The measured downloaded file size should equal the expected size of 10240 KB, confirming a complete and correct download for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.807818', '2026-08-05 10:05:20.807819');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cbe653de-95cf-4d68-9760-b98a22e9d626', 'Verify downloaded file size via SSH (Per Iteration)', 'Confirm that the download ID from the API response matches the downloadId field in the event, and that the download ID string is present within the fileLocator URL.', 'The event download ID should match the API-returned download ID, and the download ID should be present in the fileLocator URL, confirming correct download tracking for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.808218', '2026-08-05 10:05:20.808219');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cfc4893f-7bee-436b-9576-82e4ad03b0c0', 'Delete first downloaded package from device (Per Iteration)', 'Delete the downloaded validation file from the device storage using the DownloadManager delete API, providing the fileLocator URL obtained from the first download event.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.delete", "params": {"fileLocator": "<filelocator_url>"}}', 'The delete API should return SUCCESS for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.809199', '2026-08-05 10:05:20.809200');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3b530fb1-b9a6-4e8d-8125-de7947878d58', 'Verify first downloaded file is deleted from device storage (Per Iteration)', 'Verify that the downloaded file no longer exists on the DUT by executing an SSH file listing command against the file path extracted from the fileLocator URL.
ls -l <file_path>', 'The file listing command should return a "No such file or directory" response, confirming that the package was successfully removed from device storage for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.810974', '2026-08-05 10:05:20.810975');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('18779eda-b14b-4ed5-a772-19500454e50a', 'Initiate re-download of same validation file (Per Iteration)', 'Re-download the same 10 MB validation file ("10_MB_File.bin") from the configured URL using the DownloadManager download API to verify that the file can be downloaded again after deletion. Wait 15 seconds after initiating the re-download.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/10_MB_File.bin"}}', 'The re-download API should return SUCCESS and provide a new unique download ID for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.812062', '2026-08-05 10:05:20.812063');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c246cf46-39bd-437d-a3d5-04451b6e6f78', 'Verify onAppDownloadStatus event for re-download (Per Iteration)', 'Monitor the event listener buffer for up to 120 seconds to receive the onAppDownloadStatus event for the re-download. Parse the event to extract the new downloadId and fileLocator fields.', 'The onAppDownloadStatus event should be received for the re-download within the monitoring period for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.813074', '2026-08-05 10:05:20.813075');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7e2bfec7-6eda-4257-8634-175ea7a153a2', 'Verify re-download ID is unique and file size matches expected (Per Iteration)', 'Confirm that the re-download ID has not appeared in any previous iteration. Measure the size of the re-downloaded file via SSH and compare it against the expected 10240 KB.
du -sk <filelocator_url> | awk ''{print $1}''', 'The re-download ID should be unique, and the re-downloaded file size should equal 10240 KB, confirming a complete and correct re-download for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.814052', '2026-08-05 10:05:20.814053');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2d4147a0-af7d-40ae-81af-73fdb010b3d9', 'Verify disk usage remains within acceptable limit after re-download (Per Iteration)', 'Check the current disk usage of the download staging directory via SSH and verify that it is less than the initial baseline disk usage plus the expected package size (10240 KB) plus the configured MEMORY_OFFSET value.
du -sk <file_locator> | awk ''{print $1}''', 'The current disk usage should be less than initial_used_memory + 10240 + MEMORY_OFFSET, confirming that disk space usage is within acceptable limits after the re-download for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.815002', '2026-08-05 10:05:20.815003');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bd997bf0-f01f-4e53-bf52-468e58901ac8', 'Delete re-downloaded package from device (Per Iteration)', 'Delete the re-downloaded validation file from the device storage using the DownloadManager delete API, providing the fileLocator URL from the re-download event.
{"jsonrpc": "2.0", "id": 1, "method": "org.rdk.DownloadManager.delete", "params": {"fileLocator": "<filelocator_url>"}}', 'The delete API should return SUCCESS for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.816054', '2026-08-05 10:05:20.816056');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('75446aed-161a-413b-baae-4a71f972b7e8', 'Verify re-downloaded file is deleted from device storage (Per Iteration)', 'Verify that the re-downloaded file no longer exists on the DUT by executing an SSH file listing command against the file path extracted from the re-download fileLocator URL.
ls -l <file_path>', 'The file listing command should return a "No such file or directory" response, confirming that the re-downloaded package was successfully removed from device storage for each iteration.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.816432', '2026-08-05 10:05:20.816433');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bee3f627-38c6-4a64-82b2-798f5cb13769', 'Repeat download, delete, and re-download validation for all iterations', 'Repeat Steps 5 through 17 for all AppManager_test_count (100) configured iterations.', 'Every iteration should produce a unique download ID for both the initial download and the re-download, correctly measure file sizes at 10240 KB, successfully delete both downloads, and confirm disk usage remains within the configured acceptable limit throughout.', 'fd556fa8-0734-4cc9-a341-a0a54da6c9bf', '2026-08-05 10:05:20.817439', '2026-08-05 10:05:20.817441');
