INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24994315-febf-49b7-8576-3a9f650e00f2', 'STEP 1', '1. Load tdkb_e2e module
2. Import selenium module
3. Start selenium hub in TM machine
4. Start Node in lan client machine
5. Get the lan client IP
6. check if the lan client has the ip in dhcp range
7. Try to access the WEBUI of the gateway using selenium grid
8. Validate if the UI page is accessible or not
9. Disable 2.4GHZ wifi from UI
10. Check if 2.4GHZ SSID is broadcasting or not
11. Kill selenium hub and node
12.  unload module', 'The 2.4GHZ SSID should not broadcast when the 2.4GHZ SSID is disabled from UI', '7b1543b6-8968-4367-baa9-69cd6cb2c8db', '2026-07-30 09:30:11.518681', '2026-07-30 09:30:11.518683');
