INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2e0a95b9-1598-442a-9b4d-00fd6bc5ece8', 'STEP 2', 'Verify the target WAN interface is up with active IP (prerequisite)', 'Target interface should have valid inet addr', '0c389f24-9500-4177-9278-384ff62c4f3b', '2026-07-29 05:32:09.083572', '2026-07-29 05:32:09.083573');
