INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('30dc921e-2e17-4430-873b-b55f05e2ded6', 'STEP 1', '1. Load tdkb_e2e module
2. Using tdkb_e2e_Get, get and save DNSServer and lanip of GW
3. Connect the lan client and check if its assigned a valid IP by the GW
4. Get the DNS server names from the lan client
5. Check if the DNS server names from the LAN client and GW are the same or not
6.Unload tdkb_e2e module', 'DNS server names from the LAN client and GW should be the same', '85dba425-0949-42f7-bbab-ebf28571795f', '2026-07-29 11:28:05.109849', '2026-07-29 11:28:05.109852');
