INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3b9662d6-2979-41c3-adb4-a1ed0f79e300', 'STEP 1', '1. Load the modules
    2. Get the initial DM value
    3. Verify XConf server URL
    4. Configure RFC feature with MAC
    5. Set feature rule with MAC
    6. Validate feature rule with MAC
    8. Restart RFC service
    9. Query updated DM to confirm toggle
    10. Revert DM value via RFC
    11. Delete feature rule
    12. Delete feature
    13. Unload the modules', 'Restarting RFC service should update the value of the DM Device.X_Comcast_com_ParentalControl.ManagedSites.Enable.', 'a64f0e93-381b-4a57-9d45-20250061c9f6', '2026-08-05 09:05:20.353582', '2026-08-05 09:05:20.353584');
