INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3c8653ad-dddd-45ca-b097-a59fbaf0d157', 'STEP 1', '1. Load the rbus module
2. Open the rbus connection using rbus_open RBUS API
3. Create the rbus session using rbus_createSession RBUS API and store the session ID value
4. Close the created session using rbus_closeSession RBUS API with the sessionID from step 3.
5. Close the rbus connection using rbus_close RBUS API
6. Unload the module', 'The session should be crated successfully and it can be closed using the obtained sessionID', 'a9a90ebe-ff53-40d9-81cc-0ebd523d31b7', '2026-07-29 06:47:25.001929', '2026-07-29 06:47:25.001930');
