INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3f878757-335c-46ec-ad74-65d13b8ca473', 'STEP 1', '1.Load the module
2.Get the number of clients connected using Device.Hosts.HostNumberOfEntries
3.Check if the client is Ethernet using Device.Hosts.Host.{i}.Layer1Interface
4.Check if the device is active
5.Get the active and inactive time of client using Device.Hosts.Host.{i}.X_CISCO_COM_ActiveTime and
Device.Hosts.Host.{i}.X_CISCO_COM_InactiveTime and the value recieved  should be greater than zero
6.Unload the module', 'Device.Hosts.Host.{i}.X_CISCO_COM_ActiveTime and
Device.Hosts.Host.{i}.X_CISCO_COM_InactiveTime should not hold a negative value of time', 'aadd5d2f-cdab-4eed-a7fe-b8de87a13fc1', '2026-07-28 11:18:18.042838', '2026-07-28 11:18:18.042840');
