INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4ac1a2ba-2ad9-4f23-b574-2ff98827ebda', 'STEP 1', '1. Load the tr181 module.
2. Set the Device.Cellular.Interface.1.Enable as false
3.Check if Device.Cellular.X_RDK_Status be DEREGISTERED.
4.Set the Device.Cellular.Interface.1.Enable as true
5.Check if Device.Cellular.X_RDK_Status be CONNECTED.
5. Unload the tr181 module.', 'Device.Cellular.X_RDK_Status should be DEREGISTERED or CONNECTED when Device.Cellular.Interface.1.Enable is false or true respectively', '858e5dfc-41e1-400f-89c1-3567d7f1bc97', '2026-08-05 11:44:38.150282', '2026-08-05 11:44:38.150284');
