INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('74555737-ff67-447a-a4f7-73394202d4d4', 'STEP 1', '1.Configure the Function info in Test Manager GUI  which needs to be tested
