INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8c11a606-2fdd-40db-af66-00a5dd1e8b7b', 'STEP 1', '1. Load tdkb_e2e module
2. import selenium module
3. Get the value of firewall level through dmcli
