INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9190339e-a73d-47cd-99e6-109d5022323a', 'STEP 1', '1. As a pre requisite disable all other plugins and enable webkitinstance plugin.
2. Set the application URL
3. Play and pause the video from the application
3. Get the time taken to play/pause the video', 'The video must play and pause within expected range of ms.', '2197d14d-18f1-4304-8d32-f8cc16b91aa3', '2026-07-09 12:08:25.459545', '2026-07-09 12:08:25.459548');
