INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('92604141-92b0-4ded-a839-7d75300efe1e', 'STEP 1', '1.Load the module
2.Get the current self heal aggressive interval
