INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f4091d58-4570-41ae-a87b-4c516f6cff26', 'TEST STEP 4', 'Unload the modules.', 'The modules are unloaded successfully', '2a0b8761-4413-4e14-a17d-f4ccb5d3aaf5', '2026-07-30 05:02:26.424266', '2026-07-30 05:02:26.424267');
