INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('efb7d2e2-7122-41bb-b47d-b38acc0da1d0', 'STEP 1', '1. Load the E2E, Advanced Config Modules
