INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fa414de9-8273-4eea-b180-0f5143b61d50', 'STEP 1', '1. Load the modules
    2. Get the initial DM value
    3. Verify XConf server URL
    4. Configure RFC feature
    5. Set feature rule with MAC
    6. Validate feature rule with MAC
    7. Restart RFC service
    8. Query updated DM to confirm toggle
    9. Reboot the device
    10. Wait for device to come back online
    11. Query DM to confirm persistence after reboot
    12. Revert DM value via RFC
    13. Delete feature rule
    14. Delete feature
    15. Unload the modules', 'RFC feature configuration should persist across device reboot and the DM parameter should maintain the configured value.', 'e8fa68a1-f792-4790-9aff-19c904a24ce2', '2026-08-05 08:57:28.589290', '2026-08-05 08:57:28.589292');
